/**
 * Nasiya365 Service Worker
 * Strategy:
 *   - Static assets (JS/CSS/fonts/images): cache-first, update in background
 *   - API calls (/api/): network-only (never cache live data)
 *   - Navigation (HTML): network-first, offline fallback page
 */

const CACHE_NAME = "nasiya365-v2";

// Best-effort pre-cache on install. App JS/CSS are now content-hashed bundles
// (resolved at runtime, not fixed paths), so they're cached on first fetch rather
// than pre-listed here — only stable icon assets are pre-cached.
const PRECACHE_ASSETS = [
	"/assets/nasiya365/icons/icon-192.svg",
	"/assets/nasiya365/icons/icon-512.svg",
];

// ── Install ──────────────────────────────────────────────────────────────────

self.addEventListener("install", (event) => {
	self.skipWaiting();
	event.waitUntil(
		caches.open(CACHE_NAME).then((cache) =>
			Promise.allSettled(
				PRECACHE_ASSETS.map((url) => cache.add(url).catch(() => {}))
			)
		)
	);
});

// ── Activate ─────────────────────────────────────────────────────────────────

self.addEventListener("activate", (event) => {
	event.waitUntil(
		caches
			.keys()
			.then((keys) =>
				Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))
			)
			.then(() => self.clients.claim())
	);
});

// ── Fetch ─────────────────────────────────────────────────────────────────────

self.addEventListener("fetch", (event) => {
	const { request } = event;
	const url = new URL(request.url);

	// Only handle same-origin GET requests
	if (request.method !== "GET" || url.origin !== self.location.origin) return;

	// API — network only, never cache live business data
	if (url.pathname.startsWith("/api/")) return;

	// Static assets — cache-first, background refresh
	if (_isStaticAsset(url.pathname)) {
		event.respondWith(_cacheFirst(request));
		return;
	}

	// Navigation — network-first, offline fallback
	if (request.mode === "navigate") {
		event.respondWith(_networkFirst(request));
	}
});

// ── Helpers ───────────────────────────────────────────────────────────────────

function _isStaticAsset(pathname) {
	return (
		pathname.startsWith("/assets/") ||
		/\.(js|css|woff2?|ttf|otf|eot|png|jpg|jpeg|gif|svg|ico|webp)(\?|$)/.test(pathname)
	);
}

function _isCacheable(response) {
	// Cache API rejects 206 Partial Content (range responses for audio/video).
	return response.ok && response.status !== 206;
}

async function _cacheFirst(request) {
	const cached = await caches.match(request);
	if (cached) {
		// Refresh in background so next visit gets the latest
		fetch(request)
			.then(async (res) => {
				if (_isCacheable(res)) (await caches.open(CACHE_NAME)).put(request, res);
			})
			.catch(() => {});
		return cached;
	}
	try {
		const response = await fetch(request);
		if (_isCacheable(response)) (await caches.open(CACHE_NAME)).put(request, response.clone());
		return response;
	} catch {
		return new Response("", { status: 503, statusText: "Offline" });
	}
}

async function _networkFirst(request) {
	try {
		const response = await fetch(request);
		if (_isCacheable(response)) (await caches.open(CACHE_NAME)).put(request, response.clone());
		return response;
	} catch {
		const cached = await caches.match(request);
		return cached || _offlinePage();
	}
}

function _offlinePage() {
	const html = `<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Нет соединения — Nasiya365</title>
  <style>
    body{margin:0;display:flex;align-items:center;justify-content:center;
         min-height:100vh;font-family:Arial,sans-serif;background:#f4f5f7;color:#333;}
    .card{background:#fff;border-radius:12px;padding:40px 32px;text-align:center;
          box-shadow:0 4px 24px rgba(0,0,0,.08);max-width:360px;width:90%;}
    .icon{font-size:56px;margin-bottom:16px;}
    h1{margin:0 0 8px;font-size:22px;}
    p{margin:0 0 24px;color:#777;font-size:14px;}
    button{background:#0089FF;color:#fff;border:none;padding:12px 28px;
           border-radius:8px;font-size:15px;cursor:pointer;}
  </style>
</head>
<body>
  <div class="card">
    <div class="icon">📵</div>
    <h1>Нет соединения</h1>
    <p>Проверьте подключение к интернету и попробуйте снова.</p>
    <button onclick="location.reload()">Повторить</button>
  </div>
</body>
</html>`;
	return new Response(html, {
		status: 200,
		headers: { "Content-Type": "text/html; charset=utf-8" },
	});
}
